import React, { useState } from 'react';
import SourcingOfferCard from '../components/SourcingOfferCard';

const SourcingHubPage = ({ onNavigate }) => {
  const [view, setView] = useState('all'); // 'all', 'buyers', 'sellers'

  const buyerOffers = [
    {
      type: 'buy',
      crop: 'Avocado',
      variety: 'Hass',
      grade: '1',
      quantity: '10T',
      validUntil: 'July 10-20',
      price: 92,
      cert: true,
      user: 'Iviani Exporters',
      image:
        'https://images.pexels.com/photos/163688/avocados-fruit-healthy-food-163688.jpeg?auto=compress&cs=tinysrgb&w=1260&h=750&dpr=1',
    },
    {
      type: 'buy',
      crop: 'Mango',
      variety: 'Ngowe',
      grade: '1',
      quantity: '15,000 kg',
      validUntil: 'June 20-25',
      price: 30,
      cert: true,
      user: 'Vert Fresh Produce',
      image:
        'https://images.pexels.com/photos/2294477/pexels-photo-2294477.jpeg?auto=compress&cs=tinysrgb&w=1260&h=750&dpr=1',
    },
  ];

  const sellerOffers = [
    {
      type: 'sell',
      crop: 'Mango',
      variety: 'Ngowe',
      grade: '2',
      quantity: '4T',
      validUntil: 'June 22',
      price: 45,
      cert: false,
      user: 'Masongaleni Youth',
      image:
        'https://images.pexels.com/photos/6775268/pexels-photo-6775268.jpeg?auto=compress&cs=tinysrgb&w=1260&h=750&dpr=1',
    },
    {
      type: 'sell',
      crop: 'Avocado',
      variety: 'Fuerte',
      grade: '1',
      quantity: '7T',
      validUntil: 'July 5',
      price: 70,
      cert: true,
      user: 'Mavindini Growers',
      image:
        'https://images.pexels.com/photos/9738999/pexels-photo-9738999.jpeg?auto=compress&cs=tinysrgb&w=1260&h=750&dpr=1',
    },
  ];

  const offers =
    view === 'buyers'
      ? buyerOffers
      : view === 'sellers'
      ? sellerOffers
      : [...buyerOffers, ...sellerOffers];

  return (
    <div className="container mx-auto px-4 py-8">
      <header className="text-center mb-8">
        <h1 className="text-4xl font-extrabold text-[#0B3C49] dark:text-white">
          Sourcing Hub
        </h1>
        <p className="mt-2 text-lg text-gray-600 dark:text-gray-300">
          Verified buy and sell offers for export-ready produce.
        </p>
      </header>

      <div className="flex justify-center gap-4 mb-8">
        <button
          onClick={() => setView('all')}
          className={`px-4 py-2 rounded-full font-medium ${
            view === 'all'
              ? 'bg-[#1C5D57] text-white'
              : 'bg-gray-200 text-gray-700 dark:bg-gray-700 dark:text-white'
          }`}
        >
          All Offers
        </button>
        <button
          onClick={() => setView('buyers')}
          className={`px-4 py-2 rounded-full font-medium ${
            view === 'buyers'
              ? 'bg-[#1C5D57] text-white'
              : 'bg-gray-200 text-gray-700 dark:bg-gray-700 dark:text-white'
          }`}
        >
          Buyer Requests
        </button>
        <button
          onClick={() => setView('sellers')}
          className={`px-4 py-2 rounded-full font-medium ${
            view === 'sellers'
              ? 'bg-[#1C5D57] text-white'
              : 'bg-gray-200 text-gray-700 dark:bg-gray-700 dark:text-white'
          }`}
        >
          Seller Offers
        </button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
        {offers.map((offer, index) => (
          <SourcingOfferCard key={index} offer={offer} onNavigate={onNavigate} />
        ))}
      </div>
    </div>
  );
};

export default SourcingHubPage;
